// 100% Generic: Saves column names exactly as they are in Smartsheet
const clean = (val) => {
    // Converts "empty" or blanks to SQL NULLs while keeping real data as-is
    if (val === undefined || val === "" || val === "empty" || val === null) return null;
    return val;
};

let asIsData = {};

// This loops through every key in the row and keeps the original name
for (const key of Object.keys($json)) {
    asIsData[key] = clean($json[key]);
}

return asIsData;
